#!/usr/bin/env node
// Writes change-log.csv from the repository's own history. Every commit is one row.
// Opens directly in Excel or Google Sheets. Regenerated by .github/workflows/changelog.yml
// on every push, so it never needs updating by hand.
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const SEP = "\x1f";   // unit separator, git will not emit these itself
const REC = "\x1e";   // record separator

const raw = execSync(
  "git log --reverse --date=format:'%Y-%m-%d\x1f%H:%M' " +
  "--pretty=format:'\x1e%H\x1f%ad\x1f%an\x1f%s' --name-only",
  { encoding: "utf8", maxBuffer: 64 * 1024 * 1024 }
);

/* Each record starts with the separator, so a commit's file list stays with it. */
const rows = raw.split(REC).map(chunk => {
  const lines = chunk.split("\n").filter(Boolean);
  if (!lines.length) return null;
  const [hash, date, time, author, subject] = lines[0].split(SEP);
  if (!hash) return null;
  const files = lines.slice(1).filter(l => !l.includes(SEP));
  return { date, time, author: (author || "").trim(), subject, files, hash: hash.slice(0, 7) };
}).filter(Boolean);

const q = v => '"' + String(v).replace(/"/g, '""') + '"';
const csv = [
  ["Date", "Time", "Changed by", "What changed", "Files touched", "Files", "Reference"].map(q).join(","),
  ...rows.reverse().map(r => [          // newest first
    r.date, r.time, r.author, r.subject, r.files.length, r.files.join(", "), r.hash,
  ].map(q).join(",")),
].join("\n");

// byte order mark so Excel opens it as UTF-8
writeFileSync(new URL("../change-log.csv", import.meta.url), "﻿" + csv + "\n");
console.log("change-log.csv written, " + rows.length + " changes");
